using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.AI;using ROM.Horde;using MultiFPS.Gameplay.RiftEnemies;
namespace ROM.EditorTools {public static class RiftBestiaryReview {
 public static void Run(){try{RiftBestiaryBuilder.Build();EditorSceneManager.OpenScene(ProjectSceneCleanup.Rift);var world=UnityEngine.Object.FindFirstObjectByType<ROM.Horde.Horde>();var population=world.GetComponent<RiftEnemyPopulation>();var report=population.Zones.Select(z=>{int valid=z.SpawnPoints.Count(p=>p&&!world.IsSafe(p.position)&&NavMesh.SamplePosition(p.position,out var sample,12,NavMesh.AllAreas)&&!world.IsSafe(sample.position));if(valid!=z.Count)throw new Exception(z.Title+": valid spawn points "+valid+" / "+z.Count);return "PASS "+z.Title+": "+valid+" navigable points outside safe zones";}).ToArray();File.WriteAllLines("Documentation/bestiary/spawn-validation.txt",report);foreach(var path in AssetDatabase.FindAssets("t:RiftEnemyDefinition",new[]{"Assets/ROM/Enemies/Bestiary"}).Select(AssetDatabase.GUIDToAssetPath)){var definition=AssetDatabase.LoadAssetAtPath<RiftEnemyDefinition>(path);LittleDemonMaterials.Preview(definition.Prefab.gameObject,"Documentation/bestiary/"+definition.Id+".png");}Debug.Log("BESTIARY SPAWN AND VISUAL REVIEW PASS");RiftJournalProbe.RunBestiary();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
